module tb;
    reg clk;
    reg resetn;
    reg in;
    wire out;

    TopModule uut (
        .clk(clk),
        .resetn(resetn),
        .in(in),
        .out(out)
    );

    always #5 clk = ~clk;

    // Golden model
    reg [3:0] model_sr;
    wire model_out = model_sr[3];

    always @(posedge clk) begin
        if (!resetn) begin
            model_sr <= 4'b0;
        end else begin
            model_sr <= {model_sr[2:0], in};
        end
    end

    initial begin
        clk = 0;
        resetn = 0;
        in = 0;

        // Apply reset
        #12;
        resetn = 1;

        // Test random/specific inputs
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 0;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 0;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 0;
        @(posedge clk); #1; in = 0;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 0;

        // Check during reset activation mid-stream
        @(posedge clk); #1; resetn = 0; in = 1;
        @(posedge clk); #1; resetn = 1; in = 1;
        @(posedge clk); #1; in = 0;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 1;
        @(posedge clk); #1; in = 0;

        #20;
        $display("SELFTEST PASS");
        $finish;
    end

    always @(negedge clk) begin
        if (out !== model_out) begin
            $display("SELFTEST FAIL: at time %0t: out=%b, expected=%b (model_sr=%b)", $time, out, model_out, model_sr);
            $finish;
        end
    end

endmodule
